'use client';

import React, { useState, useMemo } from 'react';
import { TopUtilityBar } from '@/components/TopUtilityBar';
import { LeftSidebar } from '@/components/LeftSidebar';
import { EvidenceWorkspace } from '@/components/EvidenceWorkspace';
import { BottomPanels } from '@/components/BottomPanels';
import { DetailInspectorModal } from '@/components/DetailInspectorModal';
import { DEMO_CLAIMS, DEMO_CONFLICTS } from '@/data/demoData';
import { 
  SecurityClaim, 
  EvidenceNode, 
  ConflictItem, 
  LayerVisibility, 
  NavItem 
} from '@/types/claimtrail';

export default function DashboardPage() {
  // Navigation & View state
  const [currentNav, setCurrentNav] = useState<NavItem>('review');
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState<boolean>(false);

  // Search Query
  const [searchQuery, setSearchQuery] = useState<string>('');

  // Selected Security Claim (default to SEC-104)
  const [selectedClaimId, setSelectedClaimId] = useState<string>('claim-1');

  // Selected Evidence Node for highlighting
  const [selectedNodeId, setSelectedNodeId] = useState<string | null>('node-repo-1');

  // Layer Toggles
  const [layers, setLayers] = useState<LayerVisibility>({
    policy: true,
    repository: true,
    controls: true,
    conflicts: true,
  });

  // Modal / Detail Inspector State
  const [isInspectorOpen, setIsInspectorOpen] = useState<boolean>(false);
  const [inspectedNode, setInspectedNode] = useState<EvidenceNode | null>(null);

  // Evidence Check Running Simulation
  const [isRunningCheck, setIsRunningCheck] = useState<boolean>(false);

  // Filter claims by search query
  const filteredClaims = useMemo(() => {
    if (!searchQuery.trim()) return DEMO_CLAIMS;
    const q = searchQuery.toLowerCase();
    return DEMO_CLAIMS.filter(
      (c) =>
        c.code.toLowerCase().includes(q) ||
        c.question.toLowerCase().includes(q) ||
        c.category.toLowerCase().includes(q) ||
        c.primarySourcePath.toLowerCase().includes(q)
    );
  }, [searchQuery]);

  // Current active claim object
  const activeClaim = useMemo(() => {
    return DEMO_CLAIMS.find((c) => c.id === selectedClaimId) || DEMO_CLAIMS[0];
  }, [selectedClaimId]);

  // Aggregate stats
  const stats = useMemo(() => {
    let greenCount = 0;
    let amberCount = 0;
    let redCount = 0;

    DEMO_CLAIMS.forEach((c) => {
      if (c.status === 'green') greenCount++;
      else if (c.status === 'amber') amberCount++;
      else if (c.status === 'red') redCount++;
    });

    return {
      totalQuestions: DEMO_CLAIMS.length,
      greenCount,
      amberCount,
      redCount,
    };
  }, []);

  // Handlers
  const handleLayerToggle = (layer: keyof LayerVisibility) => {
    setLayers((prev) => ({
      ...prev,
      [layer]: !prev[layer],
    }));
  };

  const handleSelectClaim = (claim: SecurityClaim) => {
    setSelectedClaimId(claim.id);
    if (claim.nodes.length > 1) {
      setSelectedNodeId(claim.nodes[1].id);
    } else {
      setSelectedNodeId(claim.nodes[0]?.id || null);
    }
  };

  const handleSelectNode = (node: EvidenceNode) => {
    setSelectedNodeId(node.id);
    setInspectedNode(node);
    setIsInspectorOpen(true);
  };

  const handleSelectConflict = (conflict: ConflictItem) => {
    const targetClaim = DEMO_CLAIMS.find((c) => c.code === conflict.claimCode);
    if (targetClaim) {
      setSelectedClaimId(targetClaim.id);
      const conflictNode = targetClaim.nodes.find((n) => n.type === 'conflict');
      if (conflictNode) {
        setSelectedNodeId(conflictNode.id);
        setInspectedNode(conflictNode);
        setIsInspectorOpen(true);
      }
    }
  };

  const handleRunEvidenceCheck = () => {
    setIsRunningCheck(true);
    setTimeout(() => {
      setIsRunningCheck(false);
    }, 1800);
  };

  return (
    <div className="flex flex-col h-screen w-screen overflow-hidden bg-console-bg text-console-text select-none">
      {/* 1. Slim Horizontal Utility Bar (approx 44px) */}
      <TopUtilityBar
        onRunEvidenceCheck={handleRunEvidenceCheck}
        isRunningCheck={isRunningCheck}
        searchQuery={searchQuery}
        onSearchChange={setSearchQuery}
        alertCount={DEMO_CONFLICTS.length}
      />

      {/* 2. Body Area: Left Navigation (220-240px) + Main Workspace */}
      <div className="flex-1 flex overflow-hidden min-h-0 w-full">
        {/* Left Navigation Sidebar */}
        <LeftSidebar
          currentNav={currentNav}
          onNavChange={setCurrentNav}
          layers={layers}
          onLayerToggle={handleLayerToggle}
          isCollapsed={isSidebarCollapsed}
          onToggleCollapse={() => setIsSidebarCollapsed((prev) => !prev)}
          stats={stats}
        />

        {/* Main Workspace: Contains Header, 4-Column Evidence Graph, and Bottom Dock */}
        <main className="flex-1 flex flex-col min-w-0 min-h-0 overflow-hidden bg-console-bg">
          {/* Upper Section: Evidence Provenance Canvas */}
          <div className="flex-1 flex flex-col min-h-0 min-w-0 overflow-hidden">
            <EvidenceWorkspace
              claim={activeClaim}
              selectedNodeId={selectedNodeId}
              onSelectNode={handleSelectNode}
              layers={layers}
              onOpenInspector={() => {
                setInspectedNode(null);
                setIsInspectorOpen(true);
              }}
            />
          </div>

          {/* Lower Section: Bottom Dock (Claim Inspector 30%, Question Queue 43%, Conflict Feed 27%) */}
          <BottomPanels
            selectedClaim={activeClaim}
            claims={filteredClaims}
            onSelectClaim={handleSelectClaim}
            conflicts={DEMO_CONFLICTS}
            onSelectConflict={handleSelectConflict}
            onOpenFullDetail={() => {
              setInspectedNode(null);
              setIsInspectorOpen(true);
            }}
          />
        </main>
      </div>

      {/* 3. Compact Detail Inspector Modal / Dossier */}
      {isInspectorOpen && (
        <DetailInspectorModal
          claim={activeClaim}
          node={inspectedNode}
          onClose={() => setIsInspectorOpen(false)}
        />
      )}
    </div>
  );
}
